_protected_names = frozenset(
    {
        ".aws",
        ".azure",
        ".docker",
        ".env",
        ".git",
        ".gnupg",
        ".kube",
        ".netrc",
        ".npmrc",
        ".pypirc",
        ".ssh",
        ".tiny-llm",
        "id_ed25519",
        "id_rsa",
    }
)


def _protected_path_reason(parts: tuple[str, ...]) -> str | None:
    for part in parts:
        lower = part.lower()
        if lower == ".git":
            return ".git is not accessible"
        if (
            lower in _protected_names
            or lower.startswith(".env.")
            or lower.startswith(".tiny-llm-agent-")
        ):
            return "potential secret files are not accessible"
        if lower.endswith((".pem", ".key")):
            return "potential key files are not accessible"
    return None


@dataclass(frozen=True)
class _PreparedWrite:
    path: Path
    content: bytes
    expected_digest: bytes | None
    expected_mode: int | None
    after_mode: int
    parent_identity: tuple[int, int]


class _PostRenameUncertain(AgentError):
    """The target changed, but its containing directory was not made durable."""

    def __init__(self, path: Path):
        super().__init__("write completed but durability could not be confirmed")
        self.path = path


@dataclass(frozen=True)
class ToolPolicy:
    """Filesystem and command boundaries for one workspace."""

    root: Path
    allow_writes: bool = False
    allowed_commands: tuple[tuple[str, ...], ...] = ()
    max_file_bytes: int = 64 * 1024
    max_write_bytes: int = 64 * 1024
    max_list_entries: int = 200
    max_tool_output_chars: int = 16_000
    command_timeout_seconds: float = 30.0
    _root_identity: tuple[int, int] = field(init=False, repr=False, compare=False)

    def __post_init__(self) -> None:
        raw_root = Path(self.root).absolute()
        if raw_root.is_symlink():
            raise ValueError("workspace root must not be a symlink")
        root = raw_root.resolve()
        object.__setattr__(self, "root", root)
        integer_limits = (
            self.max_file_bytes,
            self.max_write_bytes,
            self.max_list_entries,
            self.max_tool_output_chars,
        )
        if any(
            isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0
            for limit in integer_limits
        ):
            raise ValueError("tool policy integer limits must be positive")
        if self.max_tool_output_chars < 64:
            raise ValueError("max tool output must leave room for command status")
        if not isinstance(self.allow_writes, bool):
            raise ValueError("allow_writes must be a boolean")
        timeout = self.command_timeout_seconds
        if isinstance(timeout, bool) or not isinstance(timeout, (int, float)):
            raise ValueError("command timeout must be a positive number")
        try:
            finite_timeout = math.isfinite(timeout)
        except OverflowError:
            finite_timeout = False
        if not finite_timeout or timeout <= 0:
            raise ValueError("command timeout must be a positive number")
        if not root.exists() or not root.is_dir():
            raise ValueError("workspace root must be an existing directory")
        root_status = os.stat(root, follow_symlinks=False)
        if not stat.S_ISDIR(root_status.st_mode):
            raise ValueError("workspace root must be a directory")
        object.__setattr__(
            self, "_root_identity", (root_status.st_dev, root_status.st_ino)
        )
        home = Path.home().resolve()
        if root.parent == root or root == home or root in home.parents:
            raise ValueError("workspace root is too broad")
        if reason := _protected_path_reason(root.parts):
            raise ValueError(f"workspace root is protected: {reason}")
        if not isinstance(self.allowed_commands, tuple):
            raise ValueError("allowed commands must be a tuple of argument tuples")
        for command in self.allowed_commands:
            if (
                not isinstance(command, tuple)
                or not command
                or any(
                    not isinstance(part, str) or not part or "\x00" in part
                    for part in command
                )
            ):
                raise ValueError("allowed commands must contain non-empty arguments")


@dataclass
class Workspace:
    """Bounded tools over one explicit workspace root."""

    policy: ToolPolicy
    confirm_tool: Callable[[ToolAction], bool] | None = None
    observed_files: dict[Path, bytes] = field(default_factory=dict, init=False)
    modified_files: set[Path] = field(default_factory=set, init=False)
    uncertain_modified_files: set[Path] = field(default_factory=set, init=False)
    receipt_store: ReceiptStore | None = field(default=None, init=False)
    last_receipt: EffectReceipt | None = field(default=None, init=False)
    _receipt_ids: set[str] = field(default_factory=set, init=False, repr=False)

    def bind_receipt_store(self, store: ReceiptStore) -> None:
        """Bind a receipt store before the first dispatched tool action."""

        if not isinstance(store, ReceiptStore):
            raise TypeError("store must be a ReceiptStore")
        if self.last_receipt is not None or self.receipt_store is not None:
            raise ValueError("receipt store must be bound exactly once before dispatch")
        self.receipt_store = store

    @property
    def available_tools(self) -> frozenset[str]:
        """Expose only tools enabled by operator policy."""

        tools = {"list_files", "read_file"}
        if self.policy.allow_writes:
            tools.update({"write_file", "edit_file"})
        if self.policy.allowed_commands:
            tools.add("run_command")
        return frozenset(tools)

    def resolve_path(self, raw: str, *, must_exist: bool = True) -> Path:
        """Resolve one relative path without escapes or symlink traversal."""

        self._validate_root()
        if not isinstance(raw, str) or not raw or "\x00" in raw:
            raise AgentError("path must be a non-empty string")
        candidate = Path(raw)
        if candidate.is_absolute():
            raise AgentError("path must be relative to the workspace")
        if ".." in candidate.parts:
            raise AgentError("path traversal is not accessible")
        if reason := _protected_path_reason(candidate.parts):
            raise AgentError(reason)
        relative = Path(*candidate.parts) if candidate.parts else Path(".")
        if relative == Path(".") and raw != ".":
            raise AgentError("path must identify a workspace entry")
        path = self.policy.root / relative
        if must_exist:
            if relative == Path("."):
                descriptor = self._open_root_directory()
                os.close(descriptor)
            else:
                parent, name = self._open_parent_directory(relative)
                try:
                    try:
                        status = os.stat(name, dir_fd=parent, follow_symlinks=False)
                    except FileNotFoundError as error:
                        raise AgentError("path does not exist") from error
                    if stat.S_ISLNK(status.st_mode):
                        raise AgentError("symlinks are not accessible")
                finally:
                    os.close(parent)
        return path

    def list_files(self, raw: str = ".") -> str:
        """List one bounded directory without exposing protected entries."""

        path = self.resolve_path(raw)
        relative_directory = path.relative_to(self.policy.root)
        directory = self._open_directory(relative_directory)
        lines: list[str] = []
        try:
            with os.scandir(directory) as entries:
                items = heapq.nsmallest(
                    self.policy.max_list_entries,
                    entries,
                    key=lambda entry: entry.name,
                )
            for item in items:
                try:
                    status = item.stat(follow_symlinks=False)
                except OSError:
                    continue
                if stat.S_ISLNK(status.st_mode):
                    continue
                relative = relative_directory / item.name
                if _protected_path_reason(relative.parts):
                    continue
                kind = "dir" if stat.S_ISDIR(status.st_mode) else "file"
                lines.append(f"{kind} {relative}")
        finally:
            os.close(directory)
        return "\n".join(lines)

    def read_file(self, raw: str) -> str:
        """Read one bounded UTF-8 regular file and remember its digest."""

        path = self.resolve_path(raw)
        data, status = self._read_bounded_regular(path, tool="read_file")
        content = data.decode("utf-8")
        self.observed_files[path] = self._digest(data)
        observed_modes = self.__dict__.setdefault("_observed_modes", {})
        observed_modes[path] = stat.S_IMODE(status.st_mode) & 0o777
        return content

    def write_file(self, raw: str, content: str) -> str:
        """Atomically create or replace an inspected file."""

        return self._commit_write(self._prepare_write(raw, content))

    def edit_file(self, raw: str, old: str, new: str) -> str:
        """Apply one exact replacement to a previously inspected file."""

        return self._commit_write(self._prepare_edit(raw, old, new))

    def run_command(self, argv: list[str]) -> str:
        """Run one exact allowlisted argument vector with a hard timeout."""

        result, _changed, _uncertain = self._run_command(self._prepare_command(argv))
        return result

    def execute(self, action: ToolAction, *, tool_call_id: str | None = None) -> str:
        """Preflight, authorize, execute, and receipt one model tool action."""

        if not isinstance(action, ToolAction):
            raise TypeError("action must be a ToolAction")
        if not isinstance(action.tool, str) or not action.tool:
            raise AgentError("tool name must be a non-empty string")
        if not isinstance(action.arguments, dict):
            raise AgentError("tool arguments must be a dictionary")
        if tool_call_id is not None and (
            not isinstance(tool_call_id, str) or not tool_call_id
        ):
            raise AgentError("tool call ID must be a non-empty string")
        call_id = tool_call_id or uuid.uuid4().hex
        try:
            arguments = json.loads(
                json.dumps(action.arguments, allow_nan=False, ensure_ascii=True)
            )
        except (TypeError, ValueError) as error:
            raise AgentError("tool arguments must be JSON serializable") from error

        if self.receipt_store is not None:
            with self.receipt_store._claim_tool_call(call_id) as claim:
                if call_id in self._receipt_ids or claim.existing is not None:
                    raise AgentError("tool call ID already has a receipt")
                self._receipt_ids.add(call_id)
                return self._execute_claimed(action, call_id, arguments, claim)
        if call_id in self._receipt_ids:
            raise AgentError("tool call ID already has a receipt")
        self._receipt_ids.add(call_id)
        return self._execute_claimed(action, call_id, arguments, None)

    def _execute_claimed(self, action, call_id, arguments, receipt_claim) -> str:
        """Dispatch one action while its durable tool-call claim is held."""

        changed: tuple[str, ...] = ()
        exit_state = "ok"
        try:
            if action.tool == "list_files":
                result = self.list_files(action.arguments.get("path", "."))
            elif action.tool == "read_file":
                result = self.read_file(action.arguments["path"])
            elif action.tool == "write_file":
                prepared = self._prepare_write(
                    action.arguments["path"], action.arguments["content"]
                )
                self._require_confirmation(action)
                result = self._commit_write(prepared)
                changed = (str(prepared.path.relative_to(self.policy.root)),)
            elif action.tool == "edit_file":
                prepared = self._prepare_edit(
                    action.arguments["path"],
                    action.arguments["old"],
                    action.arguments["new"],
                )
                self._require_confirmation(action)
                result = self._commit_write(prepared)
                changed = (str(prepared.path.relative_to(self.policy.root)),)
            elif action.tool == "run_command":
                command = self._prepare_command(action.arguments["argv"])
                self._require_confirmation(action)
                result, changed, exit_state = self._run_command(command)
            else:
                raise AgentError(f"unknown tool: {action.tool}")
        except _PostRenameUncertain as error:
            result = f"error: {error}"
            exit_state = "uncertain"
            changed = (str(error.path.relative_to(self.policy.root)),)
        except Exception as error:
            result = f"error: {error}"
            exit_state = "error"
        result = self._truncate_result(result)
        receipt = EffectReceipt(
            tool_call_id=call_id,
            tool=action.tool,
            arguments=arguments,
            exit_state=exit_state,
            result=result,
            changed_artifacts=changed,
        )
        self.last_receipt = receipt
        if receipt_claim is not None:
            receipt_claim.put(receipt)
        return result

    def _validate_root(self) -> None:
        descriptor = self._open_root_directory()
        os.close(descriptor)

    def _prepare_write(self, raw: str, content: str) -> _PreparedWrite:
        if not self.policy.allow_writes:
            raise AgentError("writes are disabled; restart with --allow-writes")
        if not isinstance(content, str):
            raise AgentError("content must be a string")
        encoded = content.encode("utf-8")
        if len(encoded) > self.policy.max_write_bytes:
            raise AgentError(f"content exceeds {self.policy.max_write_bytes} bytes")
        path = self.resolve_path(raw, must_exist=False)
        relative = path.relative_to(self.policy.root)
        if relative == Path("."):
            raise AgentError("write_file path must identify a file")
        expected_digest = self.observed_files.get(path)
        parent, name = self._open_parent_directory(relative)
        try:
            parent_status = os.fstat(parent)
            current = self._read_regular_at(parent, name, tool="write_file")
        finally:
            os.close(parent)
        if current is None:
            if expected_digest is not None:
                raise AgentError("file changed since it was read; read it again")
            expected_mode = None
            after_mode = 0o600
        else:
            if expected_digest is None:
                raise AgentError("existing files must be read before overwrite")
            current_content, current_status = current
            if self._digest(current_content) != expected_digest:
                raise AgentError("file changed since it was read; read it again")
            current_mode = stat.S_IMODE(current_status.st_mode) & 0o777
            observed_mode = self.__dict__.get("_observed_modes", {}).get(path)
            if observed_mode is None or current_mode != observed_mode:
                raise AgentError("file mode changed since it was read; read it again")
            expected_mode = observed_mode
            after_mode = expected_mode
        return _PreparedWrite(
            path=path,
            content=encoded,
            expected_digest=expected_digest,
            expected_mode=expected_mode,
            after_mode=after_mode,
            parent_identity=(parent_status.st_dev, parent_status.st_ino),
        )

    def _prepare_edit(self, raw: str, old: str, new: str) -> _PreparedWrite:
        if not isinstance(old, str) or not isinstance(new, str):
            raise AgentError("old and new text must be strings")
        if not old:
            raise AgentError("old text must not be empty")
        path = self.resolve_path(raw)
        if path not in self.observed_files:
            raise AgentError("files must be read before they are edited")
        data, current_status = self._read_bounded_regular(path, tool="edit_file")
        if self._digest(data) != self.observed_files[path]:
            raise AgentError("file changed since it was read; read it again")
        current_mode = stat.S_IMODE(current_status.st_mode) & 0o777
        if current_mode != self.__dict__.get("_observed_modes", {}).get(path):
            raise AgentError("file mode changed since it was read; read it again")
        content = data.decode("utf-8")
        matches = content.count(old)
        if matches != 1:
            raise AgentError(f"old text must match exactly once; found {matches}")
        return self._prepare_write(raw, content.replace(old, new, 1))

    def _commit_write(self, prepared: _PreparedWrite) -> str:
        self._revalidate_prepared_write(prepared)
        path = prepared.path
        self.uncertain_modified_files.add(path)
        try:
            self._atomic_write(
                path,
                prepared.content,
                expected_digest=prepared.expected_digest,
                expected_mode=prepared.expected_mode,
                after_mode=prepared.after_mode,
                parent_identity=prepared.parent_identity,
            )
        except _PostRenameUncertain:
            try:
                current, current_status = self._read_bounded_regular(
                    path, tool="write_file"
                )
            except (OSError, ValueError):
                pass
            else:
                self.observed_files[path] = self._digest(current)
                observed_modes = self.__dict__.setdefault("_observed_modes", {})
                observed_modes[path] = stat.S_IMODE(current_status.st_mode) & 0o777
            raise
        except BaseException:
            self.uncertain_modified_files.discard(path)
            raise
        self.observed_files[path] = self._digest(prepared.content)
        observed_modes = self.__dict__.setdefault("_observed_modes", {})
        observed_modes[path] = prepared.after_mode
        self.modified_files.add(path)
        self.uncertain_modified_files.discard(path)
        return f"wrote {path.relative_to(self.policy.root)}"

    def _prepare_command(self, argv: list[str]) -> tuple[str, ...]:
        if not self.policy.allowed_commands:
            raise AgentError("command execution is disabled")
        if (
            not isinstance(argv, list)
            or not argv
            or any(not isinstance(part, str) or not part for part in argv)
        ):
            raise AgentError("argv must be a non-empty array of non-empty strings")
        command = tuple(argv)
        if command not in self.policy.allowed_commands:
            raise AgentError("command is not explicitly allowed")
        return command

    def _run_command(self, argv: tuple[str, ...]) -> tuple[str, tuple[str, ...], str]:
        root = self._open_root_directory()
        try:
            process = subprocess.Popen(
                list(argv),
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                start_new_session=True,
                pass_fds=(root,),
                preexec_fn=lambda: os.fchdir(root),
            )
        finally:
            os.close(root)
        assert process.stdout is not None
        output = bytearray()

        def _reader() -> None:
            try:
                while True:
                    chunk = process.stdout.read(1 << 16)
                    if not chunk:
                        return
                    remaining = self.policy.max_tool_output_chars - len(output)
                    if remaining > 0:
                        output.extend(chunk[:remaining])
            except (OSError, ValueError):
                return

        thread = Thread(target=_reader, daemon=True)
        thread.start()
        deadline = monotonic() + self.policy.command_timeout_seconds
        timed_out = False
        while True:
            process.poll()
            group_alive = self._process_group_exists(process.pid)
            if process.returncode is not None and not group_alive:
                break
            remaining = deadline - monotonic()
            if remaining <= 0:
                timed_out = True
                self._terminate_kill_and_reap(process)
                break
            sleep(min(0.01, remaining))
        if process.returncode is None:
            process.wait()
        thread.join(timeout=0.25)
        if thread.is_alive():
            process.stdout.close()
            thread.join(timeout=0.25)
        if thread.is_alive():
            raise AgentError("command output could not be drained")
        changed_paths = self._recent_modified()
        changed = tuple(
            sorted(str(path.relative_to(self.policy.root)) for path in changed_paths)
        )
        text = bytes(output).decode("utf-8", errors="replace")
        if timed_out:
            self.uncertain_modified_files.update(changed_paths)
            status_line = (
                f"error: command timed out after "
                f"{self.policy.command_timeout_seconds:g} seconds"
            )
            return (
                self._truncate_result(text, status_line=status_line),
                changed,
                "uncertain",
            )
        return_code = process.returncode
        if return_code:
            self.uncertain_modified_files.update(changed_paths)
            status_line = f"error: command exited with code {return_code}"
            return (
                self._truncate_result(text, status_line=status_line),
                changed,
                "uncertain" if changed else "error",
            )
        self.modified_files.update(changed_paths)
        return self._truncate_result(text, status_line="exit code: 0"), changed, "ok"

    def _recent_modified(self) -> set[Path]:
        changed: set[Path] = set()
        for path, digest in self.observed_files.items():
            try:
                data = self._read_bounded_file(path, tool="run_command")
            except (OSError, UnicodeError, ValueError):
                changed.add(path)
                continue
            if self._digest(data) != digest:
                changed.add(path)
        return changed

    @staticmethod
    def _process_group_exists(process_group: int) -> bool:
        try:
            os.killpg(process_group, 0)
        except ProcessLookupError:
            return False
        except PermissionError:
            return True
        return True

    @classmethod
    def _terminate_kill_and_reap(cls, process: subprocess.Popen) -> None:
        try:
            os.killpg(process.pid, signal.SIGTERM)
        except (ProcessLookupError, PermissionError):
            try:
                process.terminate()
            except ProcessLookupError:
                pass
        grace_deadline = monotonic() + 0.1
        while monotonic() < grace_deadline:
            process.poll()
            if process.returncode is not None and not cls._process_group_exists(
                process.pid
            ):
                break
            sleep(0.01)
        if process.returncode is None or cls._process_group_exists(process.pid):
            try:
                os.killpg(process.pid, signal.SIGKILL)
            except (ProcessLookupError, PermissionError):
                try:
                    process.kill()
                except ProcessLookupError:
                    pass
        try:
            process.wait(timeout=2.0)
        except subprocess.TimeoutExpired as error:
            raise AgentError("command process could not be reaped") from error

    def _require_confirmation(self, action: ToolAction) -> None:
        if self.confirm_tool is None or not self.confirm_tool(action):
            raise AgentError(f"operator denied {action.tool}")

    def _truncate_result(self, result: str, *, status_line: str | None = None) -> str:
        suffix = f"\n[{status_line}]" if status_line else ""
        budget = self.policy.max_tool_output_chars - len(suffix)
        if budget < 0:
            return suffix[-self.policy.max_tool_output_chars :]
        if len(result) > budget:
            marker = "\n[... truncated ...]"
            result = result[: max(0, budget - len(marker))] + marker
        return result + suffix

    def _open_root_directory(self) -> int:
        flags = (
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0)
        )
        try:
            descriptor = os.open(self.policy.root, flags)
        except OSError as error:
            raise AgentError("workspace root is unavailable") from error
        status = os.fstat(descriptor)
        if (
            not stat.S_ISDIR(status.st_mode)
            or (
                status.st_dev,
                status.st_ino,
            )
            != self.policy._root_identity
        ):
            os.close(descriptor)
            raise AgentError("workspace root changed after authorization")
        return descriptor

    def _open_parent_directory(self, relative: Path) -> tuple[int, str]:
        if not relative.parts or relative.name in {"", ".", ".."}:
            raise AgentError("path is unsafe")
        flags = (
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0)
        )
        directory = self._open_root_directory()
        try:
            for part in relative.parts[:-1]:
                if part in {"", ".", ".."} or _protected_path_reason((part,)):
                    raise AgentError("path is unsafe")
                try:
                    child = os.open(part, flags, dir_fd=directory)
                except OSError as error:
                    raise AgentError("path is unsafe") from error
                os.close(directory)
                directory = child
            return directory, relative.name
        except BaseException:
            os.close(directory)
            raise

    def _open_directory(self, relative: Path) -> int:
        flags = (
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0)
        )
        if relative == Path("."):
            return self._open_root_directory()
        parent, name = self._open_parent_directory(relative)
        try:
            return os.open(name, flags, dir_fd=parent)
        except OSError as error:
            raise AgentError("list_files path must be a directory") from error
        finally:
            os.close(parent)

    def _read_regular_at(
        self, parent: int, name: str, *, tool: str
    ) -> tuple[bytes, os.stat_result] | None:
        try:
            descriptor = os.open(
                name,
                os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0),
                dir_fd=parent,
            )
        except FileNotFoundError:
            return None
        except OSError as error:
            raise AgentError(f"{tool} path is unsafe") from error
        try:
            status = os.fstat(descriptor)
            if not stat.S_ISREG(status.st_mode) or status.st_nlink != 1:
                raise AgentError(f"{tool} path is not a regular file")
            if status.st_size > self.policy.max_file_bytes:
                raise AgentError(
                    f"{tool} file exceeds {self.policy.max_file_bytes} bytes"
                )
            data = bytearray()
            while True:
                chunk = os.read(descriptor, 1 << 16)
                if not chunk:
                    break
                data.extend(chunk)
                if len(data) > self.policy.max_file_bytes:
                    raise AgentError(
                        f"{tool} file exceeds {self.policy.max_file_bytes} bytes"
                    )
            return bytes(data), status
        finally:
            os.close(descriptor)

    def _read_bounded_regular(
        self, path: Path, *, tool: str
    ) -> tuple[bytes, os.stat_result]:
        relative = path.relative_to(self.policy.root)
        parent, name = self._open_parent_directory(relative)
        try:
            current = self._read_regular_at(parent, name, tool=tool)
        finally:
            os.close(parent)
        if current is None:
            raise AgentError(f"{tool} path is unsafe or missing")
        return current

    def _read_bounded_file(self, path: Path, *, tool: str) -> bytes:
        return self._read_bounded_regular(path, tool=tool)[0]

    def _revalidate_prepared_write(self, prepared: _PreparedWrite) -> None:
        relative = prepared.path.relative_to(self.policy.root)
        parent, name = self._open_parent_directory(relative)
        try:
            current = self._read_regular_at(parent, name, tool="write_file")
        finally:
            os.close(parent)
        if current is None:
            if prepared.expected_digest is not None:
                raise AgentError("file changed since it was read; read it again")
            return
        current_content, current_status = current
        if prepared.expected_digest is None:
            raise AgentError("file changed since it was read; read it again")
        if self._digest(current_content) != prepared.expected_digest:
            raise AgentError("file changed since it was read; read it again")
        current_mode = stat.S_IMODE(current_status.st_mode) & 0o777
        if current_mode != prepared.expected_mode:
            raise AgentError("file mode changed since it was read; read it again")

    @staticmethod
    def _digest(content: bytes) -> bytes:
        return hashlib.sha256(content).digest()

    def _atomic_write(
        self,
        path: Path,
        content: bytes,
        *,
        expected_digest: bytes | None,
        expected_mode: int | None,
        after_mode: int,
        parent_identity: tuple[int, int],
    ) -> None:
        relative = path.relative_to(self.policy.root)
        parent, name = self._open_parent_directory(relative)
        temporary: str | None = None
        try:
            status = os.fstat(parent)
            if (status.st_dev, status.st_ino) != parent_identity:
                raise AgentError("parent directory changed during the write")
            current = self._read_regular_at(parent, name, tool="write_file")
            if expected_digest is None:
                if current is not None:
                    raise AgentError("file changed since it was read; read it again")
            else:
                if current is None:
                    raise AgentError("file changed since it was read; read it again")
                current_content, current_status = current
                if self._digest(current_content) != expected_digest:
                    raise AgentError("file changed since it was read; read it again")
                current_mode = stat.S_IMODE(current_status.st_mode) & 0o777
                if current_mode != expected_mode:
                    raise AgentError(
                        "file mode changed since it was read; read it again"
                    )
            temporary = f".tiny-llm-agent-{uuid.uuid4().hex}.tmp"
            descriptor = os.open(
                temporary,
                os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0),
                0o600,
                dir_fd=parent,
            )
            try:
                view = memoryview(content)
                while view:
                    written = os.write(descriptor, view)
                    view = view[written:]
                os.fchmod(descriptor, after_mode)
                os.fsync(descriptor)
            finally:
                os.close(descriptor)
            os.rename(temporary, name, src_dir_fd=parent, dst_dir_fd=parent)
            try:
                os.fsync(parent)
            except OSError as error:
                raise _PostRenameUncertain(path) from error
        finally:
            if temporary is not None:
                try:
                    os.unlink(temporary, dir_fd=parent)
                except FileNotFoundError:
                    pass
            os.close(parent)
